// orders-api - generated by the Platform POC golden path.
const http = require('http');
const port = process.env.PORT || 8080;

const server = http.createServer((req, res) => {
  if (req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({ status: 'UP' }));
  }
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ service: 'orders-api', message: 'Hello from the golden path' }));
});

server.listen(port, () => console.log('orders-api listening on ' + port));
